import "core-js/modules/es.array.includes.js";
import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.map.js";
import request from "@/utils/request";
import config from "@/config/config";
import common from "@/utils/common";
import UploadImageMore from "@/components/UploadImageMore.vue";
export default {
  name: "FoodDetail",
  mixins: [common],
  components: {
    UploadImageMore
  },
  computed: {
    userInfo() {
      return this.$store.getters.getUser || {};
    }
  },
  data() {
    return {
      foodId: null,
      foodDetail: {},
      shopInfo: {},
      commentList: [],
      commentPageNum: 1,
      commentPageSize: 10,
      commentTotal: 0,
      isFavorited: false,
      showCommentDialog: false,
      submitLoading: false,
      commentForm: {
        score: 5,
        content: '',
        images: ''
      },
      commentRules: {
        score: [{
          required: true,
          message: '请选择评分',
          trigger: 'change'
        }],
        content: [{
          required: true,
          message: '请输入评价内容',
          trigger: 'blur'
        }]
      }
    };
  },
  mounted() {
    this.foodId = this.$route.query.id;
    console.log('组件挂载，foodId:', this.foodId);
    if (this.foodId) {
      this.getFoodDetail();
      this.getShopInfo();
      this.getComments();
      // 确保 foodId 已经赋值后再检查收藏状态
      this.$nextTick(() => {
        this.checkFavorite();
      });
    }
  },
  methods: {
    // 添加 getPicUrl 方法
    getPicUrl(pic) {
      if (!pic) return '';
      // 如果 pic 是对象(已解析的 JSON),直接取 id 拼接下载 URL
      if (typeof pic === 'object' && pic.id) {
        return config.downloadUrl + pic.id;
      }
      // 如果 pic 是字符串,使用 getPicUrlByJson 处理
      return this.getPicUrlByJson(typeof pic === 'string' ? pic : JSON.stringify(pic), 0);
    },
    // 将图片 JSON 字符串转为数组
    getPicArray(picJson) {
      if (!picJson) return [];
      // 如果已经是数组,直接返回
      if (Array.isArray(picJson)) return picJson;
      // 如果是对象(不是字符串),包装成数组
      if (typeof picJson === 'object') return [picJson];
      // 如果是字符串,尝试解析
      try {
        const trimmed = picJson.trim();
        if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
          return JSON.parse(trimmed);
        }
        // 单个 URL 字符串
        return [picJson];
      } catch (e) {
        return [picJson];
      }
    },
    getFoodDetail() {
      request({
        url: config.backHost + `/api/food/info/detail/${this.foodId}`,
        method: 'POST'
      }).then(res => {
        if (res.code === 200) {
          const data = res.data;
          // 映射后端字段
          this.foodDetail = {
            id: data.id,
            foodName: data.name,
            foodPic: data.images,
            categoryId: data.categoryId,
            shopId: data.shopId,
            avgPrice: data.avgPrice,
            score: data.score,
            tags: data.tags,
            status: data.status,
            isRecommend: data.isRecommend,
            introduction: data.description,
            tasteFeature: data.tasteFeature,
            recommendReason: data.recommendReason,
            categoryName: data.categoryName,
            shopName: data.shopName
          };
        }
      });
    },
    getShopInfo() {
      if (!this.foodDetail.shopId) return;
      request({
        url: config.backHost + `/api/food/shop/detail/${this.foodDetail.shopId}`,
        method: 'POST'
      }).then(res => {
        if (res.code === 200) {
          const data = res.data;
          // 如果小吃详情中已经包含 foodShop，直接使用
          if (this.foodDetail.foodShop) {
            this.shopInfo = {
              id: this.foodDetail.foodShop.id,
              shopName: this.foodDetail.foodShop.name,
              shopPic: this.foodDetail.foodShop.images || '',
              address: this.foodDetail.foodShop.address,
              phone: this.foodDetail.foodShop.phone,
              avgPrice: this.foodDetail.foodShop.avgPrice,
              businessHours: this.foodDetail.foodShop.businessHours
            };
          } else {
            // 否则使用单独查询的结果
            this.shopInfo = {
              id: data.id,
              shopName: data.name,
              shopPic: data.images || '',
              address: data.address,
              phone: data.phone,
              avgPrice: data.avgPrice,
              businessHours: data.businessHours
            };
          }
        }
      });
    },
    getComments() {
      request({
        url: config.backHost + "/api/food/comment/listPage",
        method: 'POST',
        data: {
          params: {
            foodId: this.foodId
          },
          pageBean: {
            page: this.commentPageNum,
            pageSize: this.commentPageSize
          }
        }
      }).then(res => {
        if (res.code === 200) {
          const data = res.data;
          this.commentList = (data.records || []).map(item => ({
            id: item.id,
            foodId: item.foodId,
            userId: item.userId,
            userName: item.userName,
            userHeadPic: item.userHeadPicUrl,
            score: item.score,
            content: item.content,
            images: item.images,
            createTime: item.createTime
          }));
          this.commentTotal = data.total || 0;
        }
      });
    },
    checkFavorite() {
      if (!this.userInfo || !this.userInfo.id) {
        console.log('用户未登录，无法检查收藏状态');
        return;
      }
      console.log('检查收藏状态，foodId:', this.foodId);
      request({
        url: config.backHost + "/api/food/favorite/listPage",
        method: 'POST',
        data: {
          pageBean: {
            page: 1,
            pageSize: 100
          }
        }
      }).then(res => {
        if (res.code === 200) {
          console.log('收藏列表原始数据:', res.data);
          const data = res.data;

          // 兼容两种返回格式
          let records = [];
          if (Array.isArray(data)) {
            records = data;
          } else if (data && data.records) {
            records = data.records;
          }
          console.log('解析后的收藏记录:', records);
          if (records.length > 0) {
            console.log('第一条收藏记录:', records[0]);
          }

          // 检查当前小吃是否在收藏列表中
          const favorites = records.map(item => {
            console.log('收藏记录 item:', item, 'foodId:', item.foodId, 'foodInfoId:', item.foodInfoId);
            return item.foodId || item.foodInfoId;
          });
          console.log('所有收藏的 foodId 列表:', favorites);
          console.log('当前 foodId:', this.foodId, '是否收藏:', favorites.includes(this.foodId));
          this.isFavorited = favorites.includes(this.foodId);
        } else {
          console.error('获取收藏列表失败:', res.msg);
        }
      }).catch(err => {
        console.error('请求收藏列表出错:', err);
      });
    },
    toggleFavorite() {
      if (!this.userInfo || !this.userInfo.id) {
        this.$message.warning('请先登录');
        this.$router.push({
          name: 'login'
        });
        return;
      }

      // 判断当前是否已收藏
      const wasFavorited = this.isFavorited;
      request({
        url: config.backHost + "/api/food/favorite",
        method: 'POST',
        data: {
          foodId: this.foodId
        }
      }).then(res => {
        if (res.code === 200) {
          this.$message.success(res.msg || (wasFavorited ? '取消收藏成功' : '收藏成功'));
          // 切换收藏状态
          this.isFavorited = !wasFavorited;
        } else {
          this.$message.error(res.msg || '操作失败');
        }
      });
    },
    shareFood() {
      this.$message.info('分享功能开发中...');
    },
    submitComment() {
      this.$refs.commentForm.validate(valid => {
        if (valid) {
          this.submitLoading = true;
          request({
            url: config.backHost + "/api/food/comment/add",
            method: 'POST',
            data: {
              foodId: this.foodId,
              score: this.commentForm.score,
              content: this.commentForm.content,
              images: this.commentForm.images
            }
          }).then(res => {
            if (res.code === 200) {
              this.$message.success('评价成功');
              this.showCommentDialog = false;
              this.commentPageNum = 1;
              this.getComments();
              this.resetCommentForm();
            }
          }).finally(() => {
            this.submitLoading = false;
          });
        }
      });
    },
    resetCommentForm() {
      this.commentForm = {
        score: 5,
        content: '',
        images: ''
      };
    },
    handleCommentPageChange(page) {
      this.commentPageNum = page;
      this.getComments();
    },
    getPicArray(picJson) {
      try {
        return JSON.parse(picJson || '[]');
      } catch (e) {
        return [];
      }
    }
  }
};
